<?php
class SchoolController {
    private function go(string $p): never { redirect($p); }
    private function school(int $id): array {
        $s=DB::one('SELECT * FROM schools WHERE id=?',[$id]); if(!$s) { flash('error','Sekolah tidak ditemukan.'); redirect('/admin/sekolah'); } return $s;
    }
    function index(): void {
        $q=trim((string)($_GET['q']??'')); $status=(string)($_GET['status']??''); $w=[];$p=[];
        if($q!==''){$w[]='(s.name LIKE ? OR s.address LIKE ?)';$p[]="%$q%";$p[]="%$q%";}
        if(in_array($status,['active','inactive'],true)){$w[]='s.status=?';$p[]=$status;}
        $where=$w?'WHERE '.implode(' AND ',$w):''; $page=max(1,(int)($_GET['page']??1));
        $data=DB::paginate('s.*','schools s',$where,$p,'s.name ASC',$page,10);
        $data['q']=$q;$data['status']=$status;$data['total_schools']=(int)DB::val('SELECT COUNT(*) FROM schools');
        $data['title']='Sekolah'; render('schools/index',$data);
    }
    function create(): void { render('schools/form',['s'=>null,'title'=>'Tambah Sekolah']); }
    private function schoolInput(): array {
        $name=trim(post('name'));$address=trim(post('address'));$wa=normalize_wa(post('whatsapp'));$qty=filter_var(post('daily_portions'),FILTER_VALIDATE_INT);
        $errors=[]; if($name===''||mb_strlen($name)>150)$errors[]='Nama sekolah wajib diisi (maksimal 150 karakter).';
        if($address==='')$errors[]='Alamat lengkap wajib diisi.';if(!$wa)$errors[]='Nomor WhatsApp tidak valid.';
        if($qty===false||$qty<0)$errors[]='Jumlah porsi harus bilangan bulat nol atau lebih.';
        $status=post('status','active');if(!in_array($status,['active','inactive'],true))$errors[]='Status tidak valid.';
        return [$errors,[$name,$address,$wa,(int)$qty,$status]];
    }
    function store(): void { [$err,$d]=$this->schoolInput(); if($err){flash('error',implode(' ',$err));back('/admin/sekolah/baru');}
        DB::exec('INSERT INTO schools(name,address,whatsapp,daily_portions,status) VALUES(?,?,?,?,?)',$d);audit('sekolah_tambah',$d[0]);flash('success','Data sekolah berhasil ditambahkan.');redirect('/admin/sekolah'); }
    function show(string $id): void {
        $s=$this->school((int)$id);$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$menuFilter=(int)($_GET['menu']??0);$st=(string)($_GET['delivery_status']??'');
        $dateSql='';$params=[$s['id']];if($from!==''){$dateSql.=' AND d.delivery_date>=?';$params[]=$from;}if($to!==''){$dateSql.=' AND d.delivery_date<=?';$params[]=$to;}if($menuFilter){$dateSql.=' AND d.menu_id=?';$params[]=$menuFilter;}if(in_array($st,['preparing','in_transit','arrived','received'],true)){$dateSql.=' AND d.status=?';$params[]=$st;}
        $menus=DB::all('SELECT * FROM school_menus WHERE school_id=? ORDER BY delivery_date DESC,id DESC',[$s['id']]);
        $deliveries=DB::all("SELECT d.*,m.name menu_name FROM deliveries d JOIN school_menus m ON m.id=d.menu_id WHERE d.school_id=? $dateSql ORDER BY d.delivery_date DESC,d.id DESC LIMIT 100",$params);
        $stats=DB::one("SELECT COUNT(*) today_count,SUM(status='preparing') preparing,SUM(status='in_transit') transit,SUM(status='arrived') arrived,SUM(status='received') received,SUM(status IN ('arrived','received')) completed,SUM(eta_arrival IS NOT NULL AND eta_arrival<NOW() AND status NOT IN ('arrived','received')) late FROM deliveries WHERE school_id=? AND delivery_date=CURDATE()",[$s['id']])??[];
        $s['menu_count']=(int)DB::val('SELECT COUNT(*) FROM school_menus WHERE school_id=?',[$s['id']]);$s['planned']=(int)DB::val('SELECT COALESCE(SUM(portions),0) FROM school_menus WHERE school_id=? AND delivery_date=CURDATE()',[$s['id']]);$s['sent']=(int)DB::val("SELECT COALESCE(SUM(d.portions),0) FROM deliveries d WHERE d.school_id=? AND d.status IN ('in_transit','arrived','received')",[$s['id']]);
        $rate=(int)($stats['today_count']??0);$stats['percent']=$rate?round(((int)($stats['completed']??0))*100/$rate):0;
        $data=compact('s','menus','deliveries','stats','from','to','menuFilter','st');$data['title']='Detail Sekolah';render('schools/show',$data);
    }
    function edit(string $id): void { render('schools/form',['s'=>$this->school((int)$id),'title'=>'Edit Sekolah']); }
    function update(string $id): void { $s=$this->school((int)$id);[$err,$d]=$this->schoolInput();if($err){flash('error',implode(' ',$err));back('/admin/sekolah/'.$id.'/edit');}
        DB::exec('UPDATE schools SET name=?,address=?,whatsapp=?,daily_portions=?,status=? WHERE id=?',[...$d,$s['id']]);audit('sekolah_edit',$d[0]);flash('success','Data sekolah diperbarui.');redirect('/admin/sekolah/'.$id); }
    function toggle(string $id): void { $s=$this->school((int)$id);DB::exec('UPDATE schools SET status=? WHERE id=?',[$s['status']==='active'?'inactive':'active',$s['id']]);flash('success','Status sekolah diperbarui.');back('/admin/sekolah'); }
    function delete(string $id): void { $s=$this->school((int)$id);$n=(int)DB::val('SELECT COUNT(*) FROM school_menus WHERE school_id=?',[$s['id']]);if($n){flash('error','Sekolah mempunyai data menu/pengiriman terkait. Nonaktifkan saja agar riwayat tetap utuh.');back('/admin/sekolah');}DB::exec('DELETE FROM schools WHERE id=?',[$s['id']]);audit('sekolah_hapus',$s['name']);flash('success','Sekolah dihapus.');redirect('/admin/sekolah'); }
    function menus(): void { $schools=DB::all('SELECT id,name FROM schools WHERE status="active" ORDER BY name');$sid=(int)($_GET['school_id']??0);$date=(string)($_GET['date']??'');$q=trim((string)($_GET['q']??''));$where=[];$p=[];if($sid){$where[]='m.school_id=?';$p[]=$sid;}if($date){$where[]='m.delivery_date=?';$p[]=$date;}if($q!==''){$where[]='(m.name LIKE ? OR m.description LIKE ?)';$p[]="%$q%";$p[]="%$q%";}$sqlwhere=$where?'WHERE '.implode(' AND ',$where):'';
        $rows=DB::all("SELECT m.*,s.name school_name FROM school_menus m JOIN schools s ON s.id=m.school_id $sqlwhere ORDER BY m.delivery_date DESC,m.id DESC LIMIT 250",$p);render('schools/menus',['schools'=>$schools,'rows'=>$rows,'sid'=>$sid,'date'=>$date,'q'=>$q,'title'=>'Menu Sekolah']); }
    function saveMenus(): void { $sid=(int)post('school_id');$school=$this->school($sid);if($school['status']!=='active'){flash('error','Sekolah nonaktif tidak dapat diberi menu baru. Aktifkan sekolahnya terlebih dahulu.');back('/admin/menu');}$names=$_POST['name']??[];$descs=$_POST['description']??[];$dates=$_POST['delivery_date']??[];$portions=$_POST['portions']??[];$statuses=$_POST['menu_status']??[];$entries=[];$errors=[];
        if(!is_array($names)||count($names)>30){flash('error','Jumlah menu tidak valid.');back('/admin/menu');}
        foreach($names as $i=>$name){$name=trim((string)$name);if($name==='')continue;$dt=(string)($dates[$i]??'');$n=filter_var($portions[$i]??null,FILTER_VALIDATE_INT);$status=(string)($statuses[$i]??'available');if(strlen($name)>150||!valid_date($dt)||$n===false||$n<0||!in_array($status,['available','preparing','completed'],true))$errors[]='Salah satu menu memiliki data tidak valid.';else $entries[]=[$sid,$name,trim((string)($descs[$i]??'')),$dt,$n,$status];}
        if(!$entries)$errors[]='Isi setidaknya satu nama menu.';if($errors){flash('error',implode(' ',$errors));back('/admin/menu');}
        DB::tx(function()use($entries){foreach($entries as $e)DB::exec('INSERT INTO school_menus(school_id,name,description,delivery_date,portions,status) VALUES(?,?,?,?,?,?)',$e);});audit('menu_tambah',count($entries).' menu untuk '.$school['name']);flash('success',count($entries).' menu tersimpan.');redirect('/admin/menu?school_id='.$sid);
    }
    function updateMenu(string $id): void { $m=DB::one('SELECT * FROM school_menus WHERE id=?',[(int)$id]);if(!$m){flash('error','Menu tidak ditemukan.');back('/admin/menu');}$name=trim(post('name'));$desc=trim(post('description'));$date=post('delivery_date');$qty=filter_var(post('portions'),FILTER_VALIDATE_INT);$status=post('menu_status');if($name===''||$qty===false||$qty<0||!in_array($status,['available','preparing','completed'],true)||!valid_date($date)){flash('error','Data menu tidak valid.');back('/admin/menu');}DB::exec('UPDATE school_menus SET name=?,description=?,delivery_date=?,portions=?,status=? WHERE id=?',[$name,$desc,$date,$qty,$status,$m['id']]);flash('success','Menu diperbarui.');redirect('/admin/menu?school_id='.$m['school_id']); }
    function deleteMenu(string $id): void { $m=DB::one('SELECT * FROM school_menus WHERE id=?',[(int)$id]);if(!$m){flash('error','Menu tidak ditemukan.');back('/admin/menu');}if(DB::val('SELECT COUNT(*) FROM deliveries WHERE menu_id=?',[$m['id']])){flash('error','Menu terkait pengiriman dan tidak dapat dihapus.');back('/admin/menu');}DB::exec('DELETE FROM school_menus WHERE id=?',[$m['id']]);flash('success','Menu dihapus.');redirect('/admin/menu?school_id='.$m['school_id']); }
    function deliveries(): void { $schools=DB::all("SELECT id,name FROM schools WHERE status='active' ORDER BY name");$allmenus=DB::all("SELECT m.id,m.name,m.school_id,s.name school_name,m.delivery_date FROM school_menus m JOIN schools s ON s.id=m.school_id WHERE s.status='active' ORDER BY s.name,m.delivery_date DESC,m.name");$rows=DB::all('SELECT d.*,s.name school_name,m.name menu_name FROM deliveries d JOIN schools s ON s.id=d.school_id JOIN school_menus m ON m.id=d.menu_id ORDER BY d.delivery_date DESC,d.id DESC LIMIT 300');$staff=DB::all("SELECT id,employee_code,full_name FROM users WHERE status='active' ORDER BY full_name");render('schools/deliveries',['schools'=>$schools,'allmenus'=>$allmenus,'rows'=>$rows,'staff'=>$staff,'title'=>'Pengantaran']); }
    function createDelivery(): void { $sid=(int)post('school_id');$menu=(int)post('menu_id');$m=DB::one("SELECT m.* FROM school_menus m JOIN schools s ON s.id=m.school_id WHERE m.id=? AND m.school_id=? AND s.status='active'",[$menu,$sid]);$qty=filter_var(post('portions'),FILTER_VALIDATE_INT);$date=post('delivery_date');$staff=DB::one("SELECT full_name FROM users WHERE id=? AND status='active'",[(int)post('distributor_id')]);if(!$m||$qty===false||$qty<0||!valid_date($date)||!$staff){flash('error','Sekolah aktif, menu, tanggal, jumlah porsi, atau petugas tidak valid. Petugas harus dipilih dari data karyawan aktif.');back('/admin/pengantaran');}$distributor=$staff['full_name'];DB::tx(function()use($sid,$menu,$qty,$date,$distributor){DB::exec("INSERT INTO deliveries(school_id,menu_id,portions,delivery_date,status,distributor,notes) VALUES(?,?,?,?,'preparing',?,?)",[$sid,$menu,$qty,$date,$distributor,post('notes')]);$id=DB::id();DB::exec('INSERT INTO delivery_status_history(delivery_id,status,note,changed_by) VALUES(?,?,?,?)',[$id,'preparing','Pengiriman dibuat.',Auth::user()['id']]);});flash('success','Pengiriman dibuat.');redirect('/admin/pengantaran'); }
    function updateDelivery(string $id): void { $d=DB::one('SELECT * FROM deliveries WHERE id=?',[(int)$id]);if(!$d){flash('error','Pengiriman tidak ditemukan.');back('/admin/pengantaran');}$next=post('status');$order=['preparing','in_transit','arrived','received'];$old=array_search($d['status'],$order,true);$new=array_search($next,$order,true);if($new===false||$new!==$old+1){flash('error','Status hanya bisa dimajukan satu tahap berikutnya (Dalam Pembuatan → Dalam Pengantaran → Sampai di Sekolah → Makanan Diterima).');back('/admin/pengantaran');}$note=trim(post('notes'));DB::tx(function()use($d,$next,$note){$updates=['status=?','notes=?'];$v=[$next,$note];$field=['preparing'=>'started_at','in_transit'=>'departed_at','arrived'=>'arrived_at','received'=>'received_at'][$next];$updates[]="$field=COALESCE($field,NOW())";if($next==='in_transit')$updates[]="ready_at=COALESCE(ready_at,NOW())";DB::exec('UPDATE deliveries SET '.implode(',',$updates).' WHERE id=?',[...$v,$d['id']]);DB::exec('INSERT INTO delivery_status_history(delivery_id,status,note,changed_by) VALUES(?,?,?,?)',[$d['id'],$next,$note,Auth::user()['id']]);});flash('success','Status pengiriman diperbarui.');back('/admin/pengantaran'); }
    function eta(string $id): void { $d=DB::one('SELECT id FROM deliveries WHERE id=?',[(int)$id]);if(!$d){flash('error','Pengiriman tidak ditemukan.');back('/admin/pengantaran');}$cols=['eta_start','eta_ready','eta_departure','eta_arrival'];$values=[];foreach($cols as $c){$v=trim(post($c));$values[]=$v===''?null:$v;}foreach($values as $v)if($v!==null&&!valid_datetime_local($v)){flash('error','Format waktu estimasi tidak valid.');back('/admin/pengantaran');}DB::exec('UPDATE deliveries SET eta_start=?,eta_ready=?,eta_departure=?,eta_arrival=? WHERE id=?',[...array_map(fn($x)=>$x?str_replace('T',' ',$x).':00':null,$values),$d['id']]);flash('success','Estimasi waktu disimpan.');back('/admin/pengantaran'); }
}